TLM.f("Sancti/11-23",{"officium":"S. Clementis Papæ et Martyris","rule":["OPapaM=Cleméntem;","vide C4b;","Gloria"],"ruleInherited":["Prefatio=Apostolis"],"fallback":"Commune/C4b","from":{"Graduale":"Commune/C4b","GradualeP":"Commune/C4b","Tractus":"Commune/C4b","Evangelium":"Commune/C4b","Offertorium":"Commune/C4b","Communio":"Commune/C4b"},"sections":{"Introitus":[{"k":"ref","la":"Is 59:21; 56:7"},{"k":"text","la":"Dicit Dóminus: Sermónes mei, quos dedi in os tuum, non defícient de ore tuo: et múnera tua accépta erunt super altáre meum."},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dicit Dóminus: Sermónes mei, quos dedi in os tuum, non defícient de ore tuo: et múnera tua accépta erunt super altáre meum."}],"Oratio":[{"k":"text","la":"Gregem tuum, Pastor ætérne, placátus inténde: et, per beátum Cleméntem Mártyrem tuum atque Summum Pontíficem, perpétua protectióne custódi; quem totíus Ecclésiæ præstitísti esse pastórem."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Philippénses"},{"k":"ref","la":"Phil 3:17-21; 4:1-3"},{"k":"text","la":"Fratres: Imitatóres mei estóte, et observáte eos, qui ita ámbulant, sicut habétis formam nostram. Multi enim ámbulant, quos sæpe dicébam vobis - nunc autem et flens dico - inimícos Crucis Christi: quorum finis intéritus: quorum Deus venter est: et glória in confusióne ipsórum, qui terréna sápiunt. Nostra autem conversátio in cœlis est: unde étiam Salvatórem exspectámus, Dóminum nostrum Jesum Christum, qui reformábit corpus humilitátis nostræ, configurátum córpori claritátis suæ, secúndum operatiónem, qua étiam possit subjícere sibi ómnia. Itaque, fratres mei caríssimi et desideratíssimi, gáudium meum et coróna mea: sic state in Dómino, caríssimi. Evódiam rogo et Sýntychen déprecor idípsum sápere in Dómino. Etiam rogo et te, germáne compar, ádjuva illas, quæ mecum laboravérunt in Evangélio cum Cleménte et céteris adjutóribus meis, quorum nómina sunt in libro vitæ."}],"Graduale":[{"k":"ref","la":"Ps 106:32; 106:31"},{"k":"text","la":"Exáltent eum in ecclésia plebis: et in cáthedra seniórum laudent eum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus, et mirabília ejus fíliis hóminum.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."},{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 106:32; 106:31"},{"k":"text","la":"Exáltent eum in Ecclésia plebis: et in cáthedra seniórum laudent eum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus; et mirabília ejus fíliis hóminum","mark":"V"},{"k":"ref","la":"Ps 39:10-11"},{"k":"text","la":"Annuntiávi justítiam tuam in ecclésia magna, ecce, lábia mea non prohibébo: Dómine, tu scisti."},{"k":"text","la":"Justítiam tuam non abscóndi in corde meo: veritátem tuam et salutáre tuum dixi.","mark":"V"},{"k":"text","la":"Non abscóndi misericórdiam tuam, et veritátem tuam a concílio multo.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 16:13-19"},{"k":"text","la":"In illo témpore: Venit Jesus in partes Cæsaréæ Philíppi, et interrogábat discípulos suos, dicens: Quem dicunt hómines esse Fílium hóminis? At illi dixérunt: Alii Joánnem Baptístam, alii autem Elíam, álii vero Jeremíam, aut unum ex prophétis. Dicit illis Jesus: Vos autem quem me esse dícitis? Respóndens Simon Petrus, dixit: Tu es Christus, Fílius Dei vivi. Respóndens autem Jesus, dixit ei: Beátus es, Simon Bar Jona: quia caro et sanguis non revelávit tibi, sed Pater meus, qui in cœlis est. Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificábo Ecclésiam meam, et portæ ínferi non prævalébunt advérsus eam. Et tibi dabo claves regni cœlórum. Et quodcúmque ligáveris super terram, erit ligátum et in cœlis: et quodcúmque sólveris super terram, erit solútum et in cœlis."}],"Offertorium":[{"k":"ref","la":"Jer 1:9-10"},{"k":"text","la":"Ecce, dedi verba mea in ore tuo: ecce, constítui te super gentes et super regna, ut evéllas et déstruas, et ædífices et plantes. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Oblátis munéribus, quǽsumus, Dómine, Ecclésiam tuam benígnus illúmina: ut, et gregis tui profíciat ubíque succéssus, et grati fiant nómini tuo, te gubernánte, pastóres."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refectióne sancta enutrítam gubérna, quǽsumus, Dómine, tuam placátus Ecclésiam: ut, poténti moderatióne dirécta, et increménta libertátis accípiat et in religiónis integritáte persístat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"1534713eab58a820":{"t":"Iz 59, 21; 56, 7, Ps 111, 1\n(Iz 59, 21; 56, 7) Reče Gospodin: Moje riječi koje sam stavio na usta tvoja neće ponestati s usta tvojih. Darovi tvoji bit će mi ugodni na žrtveniku mome. (Ps 111, 1). Blago Čovjeku koji se boji Gospodina, koji se veoma raduje njegovim zapovijedima.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 59, 21; 56, 7) Reče Gospodin: Moje riječi koje sam stavio na usta tvoja neće ponestati s usta tvojih. Darovi tvoji bit će mi ugodni na žrtveniku mome.","kn":"(Is. 59 i 57) Veli Gospodin: Moje riječi, koje dadoh u usta tvoja, ne će nestati u ustima tvojima, i darovi tvoji bit će prijatni na oltaru momu. (Ps. 111, 1) Blago čovjeku, koji se boji Boga, zapovijedi njegove žudi veoma. Slava Ocu... Veli Gospodin ...","knRef":"Kniewald 1942, str. 782–783 (snimka 392) (OCR)"},"650ae42139f7a1e3":{"t":"<i>Pomolimo se</i>.\nVječni Pastiru, milosno pazi svoje stado i čuvaj vječnom zaštitom po zagovoru blaženoga Klementa, tvoga mučenika i pape koga si postavio za pastira čitave Crkve.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"3f58783f5d8249b9":{"t":"Fil 3, 17-21; 4, 1-3\nČitanje Poslanice bl. Pavla apostola Filipljanima. Braćo: Ugledajte se u mene i vladajte se prema onima koji žive po primjeru koji vam mi dajemo. Mnogi, o kojima sam vam često govorio, a sada plačući ponavljam, žive kao neprijatelji Kristova križa. Njihov će svršetak biti propast, jer im je bog trbuh i ponose se svojom sramotom. Oni teže samo za zemaljskim stvarima. Naša je, međutim, domovina na nebu, odakle i očekujemo Spasitelja, Gospodina Isusa Krista, koji će silom, kojom može sve podložiti sebi, preobraziti naše bijedno tijelo i učiniti ga jednakim svome slavnom tijelu. –: Zato, moja draga i željena braćo, radosti moja i kruno moja, ustrajte, predragi, u Gospodinu! Žarko molim Evodiju i Sintihu, da isto misle u Gospodinu. A molim i tebe, vjerni druže, da im pomogneš, jer su mi one pomogale u širenju Evanđelja zajedno s Klementom i s drugim mojim suradnicima, kojih su imena upisana u knjizi života.","kn":"Čitanje poslanice bi. Pavla apostola Filipljanima (3, 17-21, 4, 1-3). Braćo! Ugledajte se na me i promatrajte one, koji žive po primjeru, koji imate u nama. Jer mnogi, o kojima sam vam često govorio, a sada vam i sa suzama kažem, žive 'kao neprijatelji Kristova križa. Njihov svršetak je propast, njihov bog je trbuh, a slava u njihovoj sramoti, jer teže samo za zemaljskim stvarima. A naša je domovina na nebu, odakle očekujemo Spasitelja, Gospodina našega Isusa Krista. On će po jakosti, koja može sebi pokoriti sve, preobraziti naše bijedno tijelo, da bude jednako njegovu proslavljenom tijelu. Zato, moja' predraga i željkovana braćo mojaradosU i moj vijenče, tako ustrajte, predragi u Gospodinu! Evodiju molim i Sintihu prosim, ’da isto misle u Gospodinu. A i tebe, vjerni druže.i molim, pomozi onima, koji su se trumii u evanđedjii s Klementora i mojim drugim pom^- nicima, kojih su imena u knjizi života,","knRef":"Kniewald 1942, str. 430–431 (snimka 216) (OCR)"},"171509e2e2807f88":{"t":"Ps 106, 32 i 31\nNeka ga uzvisuju u narodnom zboru, neka ga hvale u vijeću staraca. Neka hvale Gospodina za dobrotu njegovu, za čudesa njegova sinovima ljudskim.\n\nMt 16, 18\n<i>Aleluja</i>, <i>aleluja</i>.\nTi si Petar–stijena, i na toj stijeni sazidat ću svoju Crkvu. <i>Aleluja</i>.","kn":"(Ps. 106, 32, 31). Slavite ga u crkvi i hvalite ga u skupštini starješina. Neka uzdižu milosrđe Gospodinovo i divna djela njegova na sinovima ljudskim.\n\nAleluja, aieluja. Ti si Petar i na toj ću stijeni sazidati crkvu svoju, aleluja.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"},"2eaad8272860ffbe":{"t":"Mt 16, 13-19\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Kad Isus dođe u krajeve Cezareje Filipove, upita učenike: Što govore ljudi, tko je Sin Čovječji? Oni rekoše: Jedni da je Ivan Krstitelj; drugi da je Ilija; treći opet da je Jeremija ili koji od proroka. Kaže im Isus: A vi, što vi kažete, tko sam ja? Šimun Petar prihvati i reče: Ti si Krist-Pomazanik, Sin Boga živoga. Nato Isus reče njemu: Blago tebi, Šimune, sine Jonin, jer ti to ne objavi tijelo i krv, nego Otac moj, koji je na nebesima. A ja tebi kažem: Ti si Petar-Stijena, i na toj stijeni sazidat ću Crkvu svoju. I vrata paklena neće je nadvladati. A tebi ću dati ključeve kraljevstva nebeskoga. Što god svežeš na zemlji bit će svezano i na nebu. A što god razriješiš na zemlji bit će razriješeno i na nebu.","kn":"t Slijedi sveto evanđelje po Mateju (16, 13-19). U ono vrijeme dođe Isus u krajeve Cezareje Filipove i upita svoje učenike; Sto kažu ljudi; Tko je Sin čovječji? Oni odgovore; Jedni kažu. da je Ivan Krstitelj, drugi Ilija, a drugi da je Jeremija ili kojigod od proroka. Isus ih upita; A vi što kažete; Tko sam ja? Simun Petar odgovori: Ti si Krist, Sin živoga Boga. Isus mu nato reče; Blago tebi, Simune, sine Jonin! Jer ti to nije objavio tijelo i krv, nego moj nebeski Otac. A ja tebi kažem: Ti si Petar, i na toj stijeni sagradit cu svoju Crkvu, i paklena je vrata ne će nadvladati. Tebi ću dati ključeve nebeskoga kraljevstva, 1 štogod svežeš na zemlji, bit će svezano i na ne-’ bu, 1 štogod razriješiš na zemlji, bit će razriješeno i na nebu.","knRef":"Kniewald 1942, str. 616–617 (snimka 309) (OCR)"},"3bfd99647c6900a1":{"t":"Jr 1, 9-10\nEvo sam stavio svoje riječi na tvoja usta. Evo sam te danas postavio nad narodima i nad kraljevstvima, da trijebiš i obaraš, gradiš i sadiš.","v":"hodie → ∅"},"465033a1b349c3e4":{"t":"Po prikaznim darovima, molimo, Gospodine, dobrostivo rasvijetli svoju Crkvu da i stado tvoje sve više i više napreduje i da ti ugode pastiri koje si postavio.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"a937e43128eeb79a":{"t":"Mt 16, 18\nTi si Petar–stijena, i na toj stijeni sazidat ću svoju Crkvu.","kn":"Ti si Petar 1 na toj ću stijeni sazidati crkvu svoju.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"},"48b397156b3ff99b":{"t":"<i>Pomolimo se</i>.\nVladaj, molimo, Gospodine, svojom Crkvom koja je nahranjena, na svetoj gozbi, da po tvome snažnom ravnanju zadobije porast slobode i ustraje u savršenom bogoštovlju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."},{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine. Allelúja."}]}}});
